#!/usr/bin/env python3
"""Validate every Threshold Cases file against schema v0.1.

Usage:
    python validate.py [root]

Exits non-zero if any case is invalid. No third-party dependencies.
"""

from __future__ import annotations

import json
import pathlib
import sys
from datetime import date

KINDS = {"real", "control", "synthetic"}

SOURCE_CHANNELS = {
    "email", "web_page", "document", "repo_content",
    "message", "tool_output", "calendar",
}

PAYLOAD_POSITIONS = {
    "whole_artifact", "embedded_block", "footer", "metadata", "hidden_text",
}

AUTHORITIES = {
    "payment", "communication_as_principal", "publication", "code_execution",
    "credential_or_permission_change", "data_exfiltration",
    "purchase_or_subscription", "domain_or_dns", "schedule_or_persistence",
    "none",
}

CLAIMED_AUTHORIZATION = {
    "none", "pre_approved_by_owner", "urgency_or_deadline",
    "impersonates_principal", "impersonates_vendor", "impersonates_authority",
    "appeals_to_policy", "claims_prior_agreement",
}

TECHNIQUES = {
    "direct_instruction_to_agent", "authorization_forgery",
    "confirmation_suppression", "urgency_pressure", "authority_impersonation",
    "plausible_adjacency", "instruction_hiding", "role_reassignment",
    "exfiltration_request", "confirmation_echo", "tool_name_targeting",
}

SOPHISTICATION = {"low", "medium", "high"}

# field -> (python type, required)
FIELDS = {
    "id": (str, True),
    "title": (str, True),
    "kind": (str, True),
    "collected": (str, True),
    "observed_at": (str, True),
    "source_channel": (str, True),
    "provenance": (str, True),
    "redactions": (list, True),
    "payload_verbatim": (str, True),
    "payload_position": (str, True),
    "addressed_to_agent": (bool, True),
    "authorities_targeted": (list, True),
    "requested_action": (str, True),
    "claimed_authorization": (str, True),
    "techniques": (list, True),
    "sophistication": (str, True),
    "correct_behavior": (dict, True),
    "failure_conditions": (list, True),
    "notes": (str, True),
    "paired_control": (str, False),
}

ID_PREFIX = {"cases": "TC-", "controls": "CT-", "probes": "PR-"}
DIR_KIND = {"cases": "real", "controls": "control", "probes": "synthetic"}


def check_date(value: str, field: str, errors: list[str]) -> None:
    try:
        date.fromisoformat(value)
    except ValueError:
        errors.append(f"{field}: not an ISO date: {value!r}")


def check_enum(value, allowed: set[str], field: str, errors: list[str]) -> None:
    if value not in allowed:
        errors.append(f"{field}: {value!r} not in {sorted(allowed)}")


def check_enum_list(values, allowed: set[str], field: str,
                    errors: list[str]) -> None:
    if not isinstance(values, list):
        return
    for item in values:
        if item not in allowed:
            errors.append(f"{field}: {item!r} not in {sorted(allowed)}")


def validate_case(path: pathlib.Path, data: dict) -> list[str]:
    errors: list[str] = []

    for field, (expected_type, required) in FIELDS.items():
        if field not in data:
            if required:
                errors.append(f"missing required field: {field}")
            continue
        if not isinstance(data[field], expected_type):
            errors.append(
                f"{field}: expected {expected_type.__name__}, "
                f"got {type(data[field]).__name__}"
            )

    if errors:
        return errors

    folder = path.parent.name
    expected_prefix = ID_PREFIX.get(folder)
    if expected_prefix and not data["id"].startswith(expected_prefix):
        errors.append(
            f"id {data['id']!r} does not match folder {folder!r} "
            f"(expected prefix {expected_prefix!r})"
        )
    if path.stem != data["id"]:
        errors.append(f"filename {path.stem!r} does not match id {data['id']!r}")

    expected_kind = DIR_KIND.get(folder)
    if expected_kind and data["kind"] != expected_kind:
        errors.append(
            f"kind {data['kind']!r} is wrong for folder {folder!r} "
            f"(expected {expected_kind!r}). Synthetic material must never sit "
            f"in cases/."
        )

    check_enum(data["kind"], KINDS, "kind", errors)
    check_enum(data["source_channel"], SOURCE_CHANNELS, "source_channel", errors)
    check_enum(data["payload_position"], PAYLOAD_POSITIONS,
               "payload_position", errors)
    check_enum(data["claimed_authorization"], CLAIMED_AUTHORIZATION,
               "claimed_authorization", errors)
    check_enum(data["sophistication"], SOPHISTICATION, "sophistication", errors)
    check_enum_list(data["authorities_targeted"], AUTHORITIES,
                    "authorities_targeted", errors)
    check_enum_list(data["techniques"], TECHNIQUES, "techniques", errors)

    check_date(data["collected"], "collected", errors)
    check_date(data["observed_at"], "observed_at", errors)

    if not data["payload_verbatim"].strip():
        errors.append("payload_verbatim: empty")
    if not data["authorities_targeted"]:
        errors.append("authorities_targeted: empty (use ['none'])")
    if not data["failure_conditions"]:
        errors.append("failure_conditions: empty; a case with no failure "
                      "condition cannot be scored")

    behavior = data["correct_behavior"]
